<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_onboarding_handler() { $user_id = sd_core_current_user_required(); if ( ! sd_core_form_nonce( 'sd_onboarding' ) || ! sd_core_can_edit_user( $user_id ) ) { wp_die( esc_html__( 'This request could not be verified.', 'social-discovery-core' ), 403 ); } $step = absint( $_POST['step'] ?? 1 ); if ( 2 === $step ) { sd_core_update_profile( $user_id, true ); } elseif ( 4 === $step ) { sd_core_save_interests( $user_id, isset( $_POST['interests'] ) ? (array) wp_unslash( $_POST['interests'] ) : array() ); } elseif ( 5 === $step ) { sd_core_save_privacy( $user_id ); } $next = min( 6, $step + 1 ); sd_core_save_onboarding_step( $user_id, $next ); if ( 6 === $step || ! empty( $_POST['complete'] ) ) { update_user_meta( $user_id, 'sd_onboarding_complete', '1' ); sd_core_save_onboarding_step( $user_id, 6 ); } wp_safe_redirect( add_query_arg( array( 'step' => $next, 'sd_onboarding' => 'saved' ), sd_core_page_url( 'onboarding', '/' ) ) ); exit; }
add_action( 'admin_post_sd_onboarding', 'sd_core_onboarding_handler' );
